const $=s=>document.querySelector(s);let original,state,mode='design',timer;const key='business-live-editor-v1';
const bridge=`<script>addEventListener('message',e=>{if(e.source!==parent||e.data.type!=='css')return;document.getElementById('live-override').textContent=e.data.css});<\/script>`;
function doc(){return '<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="'+location.href.replace(/[^/]*$/,'')+'"><style id="live-override">'+state.css+'</style></head><body>'+state.html+bridge+'</body></html>'}
function render(){if(mode==='design'){$('#frame').removeAttribute('src');$('#frame').srcdoc=doc()}else{$('#frame').removeAttribute('srcdoc');$('#frame').src='game.html'}$('#design').classList.toggle('active',mode==='design');$('#play').classList.toggle('active',mode==='play')}
function cssApply(){$('#frame').contentWindow.postMessage({type:'css',css:state.css},location.origin)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('#status').textContent='자동 저장됨'}catch{$('#status').textContent='저장 공간 부족 · 내보내기 가능'}}
function colors(){const wrap=$('#swatches');wrap.replaceChildren();for(const k of Object.keys(original.palette)){const matches=[...state.css.matchAll(new RegExp('--'+k+'\\s*:\\s*(#[0-9a-fA-F]{6})','g'))];const val=matches.at(-1)?.[1]||'#'+original.palette[k];const label=document.createElement('label');label.className='swatch';const input=document.createElement('input');input.type='color';input.value=val;input.setAttribute('aria-label','--'+k);const span=document.createElement('span'),b=document.createElement('b'),hex=document.createElement('span');b.textContent='--'+k;hex.textContent=val;span.append(b,hex);label.append(input,span);wrap.append(label);input.oninput=()=>{state.css=state.css.replace(new RegExp('(--'+k+'\\s*:\\s*)#[0-9a-fA-F]{6}','g'),'$1'+input.value);hex.textContent=input.value;$('#cssCode').value=state.css;cssApply();save()}}}
function tab(name){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==name);if(name==='palette')colors()}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('#cssCode').oninput=()=>{state.css=$('#cssCode').value;cssApply();save()};$('#htmlCode').oninput=()=>{state.html=$('#htmlCode').value;clearTimeout(timer);timer=setTimeout(()=>{mode='design';render();save()},400)};$('#frame').onload=cssApply;$('#design').onclick=()=>{mode='design';render()};$('#play').onclick=()=>{mode='play';render()};$('#width').onchange=()=>{$('#frame').style.width=$('#width').value;$('#frame').style.flexShrink='0'};$('#reset').onclick=()=>{if(!confirm('수정 내용을 버리고 원본과 기본 팔레트로 돌아갈까요?'))return;state={html:original.html,css:original.css};$('#cssCode').value=state.css;$('#htmlCode').value=state.html;colors();render();save()};$('#download').onclick=async()=>{let content;if(mode==='play'){content=await(await fetch('game.html')).text();content=content.replace('</head>','<style>'+state.css+'</style></head>')}else{content=doc().replace(bridge,'')}for(const asset of [...new Set(content.match(/asset-\d+\.[a-z0-9]+/g)||[])]){const blob=await(await fetch(asset)).blob();const data=await new Promise(resolve=>{const reader=new FileReader;reader.onload=()=>resolve(reader.result);reader.readAsDataURL(blob)});content=content.split(asset).join(data)}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:'text/html'}));a.download=mode==='play'?'business-game.html':'business-layout.html';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
fetch('data.json').then(r=>r.json()).then(data=>{original=data;try{state=JSON.parse(localStorage.getItem(key))}catch{}if(!state||typeof state.css!=='string'||typeof state.html!=='string')state={css:data.css,html:data.html};$('#cssCode').value=state.css;$('#htmlCode').value=state.html;colors();render();$('#status').textContent='실시간 반영 중'}).catch(()=>$('#status').textContent='파일을 불러오지 못했습니다');
